use super::*;
use nirvana::ir::{Assignment, BinaryOp, Control, Expr, IrInstruction, Place, UnaryOp, Width};
use nirvana::block_verify::region::extraction::repeat::{unfold, Prefixed, Completion};
#[path = "/home/hosi/nirvana/tests/support/native.rs"]
mod native;
#[path = "/home/hosi/nirvana/tests/support/checked_c.rs"]
mod checked_c;
include!(concat!(env!("CARGO_MANIFEST_DIR"), "/.git/nirvana-actual-loop-source.rs"));
#[test]
#[ignore]
fn exit_specific_loop_candidate_pilot() {
    let r = |n| Expr::Register(Reg(n)); let k = Expr::Const; let op = Expr::binary;
    let set = |n, value| Assignment { destination: Reg(n).into(), value };
    let step = |address, assignments, control| IrInstruction { address, size: 1, assignments, control };
    let source = Program::new(0, 14, source_instructions()).unwrap();
    let dump = format!("entry=0 registers=13\n{:#?}\n", source.instructions());
    assert_eq!(dump, std::fs::read_to_string("target/checkpoints/ir-entry-storage-v1/printed-storage.ir.txt").unwrap());
    let widths = ValueWidths::analyze(&source);
    let before = extract(&source, 32, &[32, 198, 375], Some(&widths)).unwrap();
    let directory = std::path::PathBuf::from(std::env::var("NIRVANA_LOOP_OUT").unwrap());
    for wrong in [false, true] {
        let mut instructions = source.instructions().to_vec();
        let first = instructions.iter_mut().find(|i| i.address == 32).unwrap();
        let mut masks: Vec<_> = before.input_bit_caps().iter().enumerate().filter(|(_, bits)| **bits < 64).map(|(reg, bits)| set(reg, op(BinaryOp::And, r(reg), k((1u64 << bits) - 1)))).collect();
        masks.append(&mut first.assignments); first.assignments = masks;
        let route = instructions.iter_mut().find(|i| i.address == 110).unwrap(); route.control = Control::Jump(500);
        let index = op(BinaryOp::Add, r(6), r(13));
        let load = Expr::load(op(BinaryOp::Add, r(2), op(BinaryOp::Mul, op(BinaryOp::And, index.clone(), k(3)), k(8))), Width::U64);
        instructions.extend([
            step(500, vec![set(13, k(1))], Control::Jump(501)),
            step(501, vec![set(8, load), set(9, op(BinaryOp::Add, r(9), op(BinaryOp::Xor, r(8), if wrong { index.clone() } else { r(7) }))), Assignment { destination: Place::Memory { address: op(BinaryOp::Add, k(16), r(2)), width: Width::U64 }, value: r(9) }, set(8, op(BinaryOp::Xor, r(9), r(5)))], Control::Branch { condition: op(BinaryOp::Eq, op(BinaryOp::And, r(8), k(7)), k(0)), target: 375 }),
            step(502, vec![], Control::Branch { condition: op(BinaryOp::Eq, op(BinaryOp::And, r(9), k(3)), k(1)), target: 509 }),
            step(503, vec![set(8, op(BinaryOp::Add, r(5), op(BinaryOp::And, r(9), k(15))))], Control::Branch { condition: op(BinaryOp::Eq, r(13), r(12)), target: 507 }),
            step(504, vec![set(5, r(8)), set(13, op(BinaryOp::Add, r(13), k(1)))], Control::Jump(501)),
            step(506, vec![], Control::Branch { condition: op(BinaryOp::Ult, r(13), k(3)), target: 508 }),
            step(507, vec![], Control::Jump(198)),
            step(508, vec![set(5, r(8))], Control::Jump(198)),
            step(509, vec![set(5, op(BinaryOp::Xor, r(5), index)), set(8, r(5))], Control::Jump(198)),
        ]);
        let candidate = Program::new(0, 14, instructions).unwrap();
        if !wrong {
            let out = nirvana::readable::emit_readable_c_with_options(&candidate, nirvana::readable::ReadableOptions { stack_register: Some(Reg(1)), recover_objects: true, coalesce_locals: true, compact_memory: true }).unwrap();
            std::fs::write(directory.join("candidate.c"), &out.code).unwrap();
            std::fs::write(directory.join("candidate-params.txt"), format!("{:?} locals={} fallback={:?}\n", out.parameters, out.locals.len(), out.fallback_reason)).unwrap();
            let harness = checked_c::source_with_stack(&out, 14, 4, 512, 4600);
            assert!(harness.contains("registers[7]=address;") && harness.contains("registers[4]=UINT64_C(4600);"));
            let harness = harness.replace("registers[7]=address;", "registers[2]=address;").replace("registers[4]=UINT64_C(4600);", "registers[1]=UINT64_C(4600);");
            let path = directory.join("candidate-harness.c"); std::fs::write(&path, harness).unwrap();
            let vectors = std::fs::read_to_string("tools/corpora/structure-nested-v1.inputs.txt").unwrap();
            let mut rows = Vec::new(); let mut expected = Vec::new();
            for line in vectors.lines().filter(|l| !l.trim().is_empty()) {
                let words: Vec<u64> = line.split_whitespace().map(|x| x.parse().unwrap()).collect();
                for address in [4224u64,4576,4095,4608,u64::MAX] {
                    let mut memory: Vec<u8> = (0..512usize).map(|i| (i*29+7)as u8).collect();
                    for (n,value) in words.iter().enumerate() { if let Some(location) = address.checked_add(n as u64*8).and_then(|v| v.checked_sub(4096)).filter(|&v| v<=504) { memory[location as usize..location as usize+8].copy_from_slice(&value.to_le_bytes()); } }
