    let raw=nirvana::frontend::lift_elf_auto(bytes,function).map_err(|_|"lift")?.program;
    let middle=nirvana::middle_ir::Function::from_low(&raw).map_err(|_|"middle")?;
    let output=readable::emit_middle_c_with_storage_provenance(&middle,ReadableOptions{stack_register:Some(Reg(nirvana::x86::RSP)),recover_objects:true,coalesce_locals:true,compact_memory:true}).map_err(|_|"display")?;
    let SignedStorageProvenance::Captured(snapshot)=output.signed_storage_provenance else{return Err("capture")};
    let source=&snapshot.source;
    let dense=compact(source).map_err(|_|"source-projection")?;
    let eligible:Vec<_>=dense.registers().iter().filter(|r|!output.parameters.contains(r)).copied().collect();
    let allocation=nirvana::allocation::allocate_locals(source,&eligible).ok_or("allocation")?;
    let mapping:Vec<_>=eligible.iter().map(|&r|(r,allocation.color(r).unwrap())).collect();
    let storage=nirvana::transform::allocated_storage::lower(source,&mapping).map_err(|_|"storage")?;
    let dense=compact(storage.program()).map_err(|_|"physical-projection")?;
    let found=nirvana::lane_patterns::discover(dense.program()).map_err(|_|"discovery")?;
    Ok((found.kernels().len(),found.groups().len()))
}
#[test]
#[ignore]
fn lane_shadow_corpus_aggregate() {
    let text=std::fs::read_to_string(std::env::var("NIRVANA_LANE_INDEX").unwrap()).unwrap();
    let mut totals=std::collections::BTreeMap::<String,[usize;5]>::new();
    let mut failed=std::collections::BTreeMap::<String,usize>::new();
    for row in text.lines() {
        let fields:Vec<_>=row.split('\t').collect();assert_eq!(fields.len(),3);
        let cohort=fields[0];let total=totals.entry(cohort.to_owned()).or_default();total[0]+=1;
        let bytes=std::fs::read(fields[2]).unwrap();
        match inspect(&bytes,fields[1]) {
            Ok((kernels,groups))=>{total[1]+=1;total[2]+=kernels;total[3]+=groups;total[4]+=usize::from(groups>0);}
            Err(stage)=>{*failed.entry(format!("{cohort}:{stage}")).or_default()+=1;}
        }
    }
    println!("LANE-SHADOW columns=profiles,analyzed,kernels,groups,profiles_with_groups totals={totals:?} unavailable={failed:?}");
}

