use super::*;
use nirvana::ir::{Assignment,BinaryOp,Control,Expr,IrInstruction,Place,UnaryOp,Width};
include!(concat!(env!("CARGO_MANIFEST_DIR"), "/.git/nirvana-actual-loop-source.rs"));
#[test]
#[ignore]
fn automatic_lane_boundary_pilot() {
 let source=Program::new(0,14,source_instructions()).unwrap();
 let found=nirvana::lane_patterns::discover(&source).unwrap();
 let group=&found.groups()[0];let cfg=source.cfg();
 let block_for=|pc| {let index=source.instructions().iter().position(|i|i.address==pc).unwrap();cfg.blocks().iter().find(|block|block.instructions.contains(&index)).unwrap().id};
 let members:Vec<_>=group.kernels.iter().map(|kernel|block_for(kernel.load.instruction)).collect();
 let analysis=ControlFlowAnalysis::compute(cfg).unwrap();
 let natural=analysis.natural_loops().iter().filter(|natural|members.iter().all(|block|natural.body.contains(block))).min_by_key(|natural|natural.body.len()).unwrap();
 let mut abrupt=BTreeSet::new();
 for &id in &natural.body {
  if natural.latches.contains(&id){continue;}
  for edge in &cfg.block(id).successors {
   let Target::Block(mut target)=edge.target else{panic!("closed source")};
   if natural.body.contains(&target){continue;}
   let mut seen=BTreeSet::new();
   while seen.insert(target) {
    let block=cfg.block(target);let instructions=&source.instructions()[block.instructions.clone()];
    if instructions.iter().flat_map(|instruction|&instruction.assignments).any(|assignment|!matches!((&assignment.destination,&assignment.value),(Place::Register(d),Expr::Register(s))if d==s)){break;}
    let Control::Jump(pc)=instructions.last().unwrap().control else{break;};
    let next=cfg.block_at(pc).unwrap();if natural.body.contains(&next){break;}
    target=next;
   }
   abrupt.insert(cfg.block(target).start);
  }
 }
 let header=cfg.block(natural.header).start;
 let latches:Vec<_>=natural.latches.iter().map(|&id|cfg.block(id).start).collect();
 let mut stops=BTreeSet::from([header]);stops.extend(latches.iter().copied());stops.extend(abrupt.iter().copied());
 let stops:Vec<_>=stops.into_iter().collect();
 let widths=ValueWidths::analyze(&source);
 let region=extract(&source,header,&stops,Some(&widths)).unwrap();
 let interface=nirvana::block_verify::region::extraction::live_out::derive(&region).unwrap();
 assert!(interface.matches(&region));
 println!("AUTO-BOUNDARY header={header} first_lane={} latches={latches:?} abrupt={abrupt:?} stops={stops:?} region_steps={} interface_rows={}",cfg.block(members[0]).start,region.program().instructions().len(),interface.returns().len());
 assert_eq!(header,32);assert_eq!(cfg.block(members[0]).start,110);assert_eq!(latches,[198]);assert_eq!(abrupt,BTreeSet::from([375]));
 let baseline=extract(&source,32,&[32,198,375],Some(&widths)).unwrap();
 assert_eq!(region.program().instructions(),baseline.program().instructions());
 println!("AUTO-BOUNDARY baseline_projection_identical=true hints=false");
}

