use super::*;
#[test]
#[ignore]
fn partition_sat_extraction_obeys_one_deadline() {
 use std::os::unix::fs::PermissionsExt;
 let directory=std::path::PathBuf::from(std::env::var("NIRVANA_BUDGET_DIR").unwrap());
 let script=directory.join("slow-solver");
 std::fs::write(&script,b"#!/bin/sh\ncat >/dev/null\nprintf 'call\\n' >> \"$0.calls\"\nsleep 0.10\nprintf 'sat\\n'\n").unwrap();
 std::fs::set_permissions(&script,std::fs::Permissions::from_mode(0o700)).unwrap();
 let source=|value|Program::new(0,1,vec![nirvana::ir::IrInstruction{address:0,size:1,assignments:vec![],control:nirvana::ir::Control::Return(nirvana::ir::Expr::Const(value))}]).unwrap();
 let q=nirvana::block_verify::region::query(&source(1),&source(2),&[],&[]).unwrap();
 let solver=Solver::new(script.clone()).with_timeout(std::time::Duration::from_secs(5));
 let start=std::time::Instant::now();
 let report=q.input_partitions(Reg(0),1).unwrap().check(&solver,std::time::Duration::from_millis(150));
 let elapsed=start.elapsed().as_millis();
 let calls=std::fs::read_to_string(script.with_extension("calls")).unwrap().lines().count();
 assert!(matches!(report.verdict,Verdict::Unknown(nirvana::verify::UnknownReason::SolverTimeout)),"{report:?}");
 assert!(calls<=2,"the model extraction process must not start after the shared deadline");
 assert!(elapsed<500,"deadline propagation took {elapsed}ms");
 println!("PARTITION-BUDGET budget_ms=150 elapsed_ms={elapsed} solver_calls={calls} checked={} total={} result=SolverTimeout shared_sat_extraction=true",report.checked,report.total);
}
